base<-read.csv('outputs/stage6_foxp2_gnomad_narrow_variants.csv');d<-read.csv('outputs/stage6_gong_foxp2_factor_aligned.csv');fits<-readRDS('work/stage6_foxp2_gnomad_ancestry_matched_fits.rds');out<-list();for(nm in c('MVP_effN','HFRS')){f<-fits[[nm]];i<-f$sets$cs[[1]];a<-f$alpha[f$sets$cs_index[1],i];hit<-base$rs[i]%in%d$rs;out[[length(out)+1]]<-data.frame(trait=nm,credible_variants=length(i),retained_variants=sum(hit),component_mass_in_credible_set=sum(a),component_mass_retained=sum(a[hit]),fraction_credible_mass_retained=sum(a[hit])/sum(a))};write.csv(do.call(rbind,out),'outputs/stage6_gong_foxp2_credible_coverage.csv',row.names=FALSE);print(do.call(rbind,out))
